EMBEDDED_IMAGES = {
    "delhi_backdrop.jpg": "",
    "delhi_clean.jpg": "",
    "delhi_polluted.jpg": "",
    "inhaling.jpg": "",
}


@st.cache_data(show_spinner=False)
def img_uri(name, blur=0, max_w=1600):
    """Return a data: URI for an embedded image, optionally blurred / downsized."""
    raw_b64 = EMBEDDED_IMAGES.get(name)
    if raw_b64 is None:
        return ""
    if not blur and max_w >= 1280:
        return "data:image/jpeg;base64," + raw_b64
    try:
        from PIL import Image, ImageFilter
        im = Image.open(io.BytesIO(base64.b64decode(raw_b64))).convert("RGB")
        im.thumbnail((max_w, max_w))
        if blur:
            im = im.filter(ImageFilter.GaussianBlur(blur))
        buf = io.BytesIO()
        im.save(buf, format="JPEG", quality=72)
        return "data:image/jpeg;base64," + base64.b64encode(buf.getvalue()).decode()
    except Exception:
        return "data:image/jpeg;base64," + raw_b64


