def sky_layer(n=8, seed=3, strength=0.55, top_range=(2, 70), size=(220, 520)):
    rng = random.Random(seed)
    out = []
    for _ in range(n):
        dur = rng.uniform(80, 170)
        out.append(f'<div class="cloud" style="top:{rng.uniform(*top_range):.1f}%;width:{rng.uniform(*size):.0f}px;'
                   f'opacity:{rng.uniform(0.45, 1.0) * strength:.2f};animation-duration:{dur:.0f}s;'
                   f'animation-delay:-{rng.uniform(0, dur):.0f}s"></div>')
    return '<div class="sky">' + "".join(out) + "</div>"


def particles(n, seed=7, rgb="255,214,170", max_size=6.0, rise=140):
    rng = random.Random(seed)
    dots = []
    for _ in range(int(n)):
        s, o, d = rng.uniform(1.5, max_size), rng.uniform(0.35, 0.95), rng.uniform(7, 20)
        dots.append(f'<span class="pt" style="left:{rng.uniform(0, 100):.1f}%;top:{rng.uniform(5, 100):.1f}%;'
                    f'width:{s:.1f}px;height:{s:.1f}px;--dx:{rng.uniform(-70, 70):.0f}px;--rise:-{rise}px;'
                    f'--o:{o:.2f};background:rgba({rgb},{o:.2f});box-shadow:0 0 {s * 2:.0f}px rgba({rgb},.8);'
                    f'animation-duration:{d:.1f}s;animation-delay:-{rng.uniform(0, d):.1f}s"></span>')
    return '<div class="particles">' + "".join(dots) + "</div>"


