def stat_card(label, value, sub="", color="#38bdf8", delay=0, bar=None):
    b = (f'<div class="bar" style="--c:{color};margin-top:.6rem"><div style="width:{bar:.0f}%"></div></div>'
         if bar is not None else "")
    return (f'<div class="stat fade-up" style="--accent:{color};animation-delay:{delay}ms">'
            f'<div class="stat-label">{label}</div><div class="stat-value" style="color:{color}">{value}</div>'
            f'{b}<div class="stat-sub">{sub}</div></div>')


def style_fig(fig, height=360):
    fig.update_layout(
        height=height, margin=dict(l=10, r=10, t=48, b=10),
        paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="#cbd5e1", family="Poppins, Inter, sans-serif", size=12),
        hoverlabel=dict(bgcolor="rgba(15,23,42,.95)", bordercolor="rgba(255,255,255,.15)",
                        font=dict(color="white", family="Poppins, sans-serif")),
        legend=dict(orientation="h", y=1.02, yanchor="bottom", x=0, bgcolor="rgba(0,0,0,0)", font=dict(color="#e2e8f0", size=12)),
        xaxis=dict(gridcolor="rgba(255,255,255,.05)", zeroline=False, linecolor="rgba(255,255,255,.1)",
                   tickfont=dict(color="#94a3b8"), title_font=dict(color="#94a3b8")),
        yaxis=dict(gridcolor="rgba(255,255,255,.07)", zeroline=False, tickfont=dict(color="#94a3b8"), title_font=dict(color="#94a3b8")),
    )
    return fig


def add_category_lines(fig, ymax):
    for lvl, lab in [(100, "Satisfactory"), (200, "Moderate"), (300, "Poor"), (400, "Very Poor")]:
        if lvl < ymax:
            fig.add_hline(y=lvl, line=dict(color="rgba(255,255,255,.22)", dash="dot", width=1),
                          annotation_text=f"{lvl} · {lab}", annotation_font=dict(color="#cbd5e1", size=10),
                          annotation_bgcolor="rgba(5,8,18,.7)", annotation_position="top right")


